36	/**
37	 * Get the file path for a cache mapping file.
38	 * Cache mappings are stored directly on filesystem (not through media storage)
39	 * to avoid content-based key generation.
40	 */
41	export function getCacheMappingPath(cacheKey: string): string {
42	  const basePath = path.join(getConfigDirectoryPath(true), MEDIA_DIR);
43	  const cacheDir = path.join(basePath, CACHE_DIR);
44	  // Ensure directory exists
45	  if (!fs.existsSync(cacheDir)) {
46	    fs.mkdirSync(cacheDir, { recursive: true });
47	  }
48	  return path.join(cacheDir, `${cacheKey}.json`);
49	}
